use std::env;
use std::fs;
const MAGIC:u32=0x5042_4637; const KNOWN_MASK:u32=0x3f; const CURRENT_VERSION:u16=5; const CURRENT_MASK:u32=0x3f; const CURRENT_DIGEST:u64=0xc43c_d04d_f228_379f; const STATEMENT:u64=0xfedc_ba98_7654_3210; const AUTHORITY:u32=0xa17e_0007; const EPOCH:u32=7; const TOKEN_BYTES:usize=56;
fn hex_decode(s:&str)->Option<Vec<u8>>{if s.len()%2!=0{return None} let mut out=Vec::with_capacity(s.len()/2); let b=s.as_bytes(); fn n(c:u8)->Option<u8>{match c{b'0'..=b'9'=>Some(c-b'0'),b'a'..=b'f'=>Some(c-b'a'+10),b'A'..=b'F'=>Some(c-b'A'+10),_=>None}} let mut i=0; while i<b.len(){out.push((n(b[i])?<<4)|n(b[i+1])?); i+=2} Some(out)}
fn u16be(b:&[u8],i:usize)->u16{u16::from_be_bytes([b[i],b[i+1]])} fn u32be(b:&[u8],i:usize)->u32{u32::from_be_bytes([b[i],b[i+1],b[i+2],b[i+3]])} fn u64be(b:&[u8],i:usize)->u64{u64::from_be_bytes([b[i],b[i+1],b[i+2],b[i+3],b[i+4],b[i+5],b[i+6],b[i+7]])}
fn parse_policy(hex:&str)->Option<(u16,u32,u64)>{let b=hex_decode(hex)?; if b.len()!=16||u16be(&b,2)!=0{return None} Some((u16be(&b,0),u32be(&b,4),u64be(&b,8)))}
fn validate(b:&[u8],mode:&str,policy_hex:Option<&str>)->bool{if b.len()!=TOKEN_BYTES{return false} let policy=if mode=="manual"{Some((CURRENT_VERSION,CURRENT_MASK,CURRENT_DIGEST))}else{policy_hex.and_then(parse_policy)}; let(pv,pm,pd)=match policy{Some(x)=>x,None=>return false}; let magic=u32be(b,0); let version=u16be(b,4); let flags=u16be(b,6); let mask=u32be(b,8); let digest=u64be(b,12); let statement=u64be(b,20); let authority=u32be(b,28); let epoch=u32be(b,32); let replay=u64be(b,36); let provenance=u64be(b,44); let outcome=b[52]; if magic!=MAGIC||flags!=0||b[53]!=0||b[54]!=0||b[55]!=0{return false} if version!=pv||mask!=pm||(mask & !KNOWN_MASK)!=0{return false} if digest!=pd||statement!=STATEMENT||authority!=AUTHORITY||epoch!=EPOCH{return false} if(mask&0x08)!=0&&replay==0{return false} if(mask&0x10)!=0&&provenance==0{return false} if(mask&0x20)!=0&&outcome!=1{return false} true}
fn main(){let args:Vec<String>=env::args().collect(); let mut mode=None; let mut policy_hex=None; let mut input=None; let mut i=1; while i<args.len(){match args[i].as_str(){"--mode"=>{i+=1;if i<args.len(){mode=Some(args[i].clone())}},"--policy-hex"=>{i+=1;if i<args.len(){policy_hex=Some(args[i].clone())}},other=>input=Some(other.to_string())} i+=1} let mode=mode.unwrap_or_default(); if mode!="manual"&&mode!="canonical"&&mode!="proofbit"{std::process::exit(2)} let input=match input{Some(x)=>x,None=>std::process::exit(2)}; let text=fs::read_to_string(input).expect("input"); let mut out=String::new(); for line in text.lines().filter(|x|!x.is_empty()){let mut p=line.splitn(3,'\t'); let name=p.next().unwrap_or(""); let _=p.next(); let raw_hex=p.next().unwrap_or(""); let accepted=hex_decode(raw_hex).map(|b|validate(&b,&mode,policy_hex.as_deref())).unwrap_or(false); out.push_str(name); out.push('\t'); out.push(if accepted{'1'}else{'0'}); out.push('\n')} print!("{}",out)}
